"""Build the portfolio documentation from the supplied snap-fit case (read-only)."""
from pathlib import Path
from html import escape
import csv, shutil, subprocess

ROOT = Path(__file__).resolve().parents[1]
SOURCE = Path('E:/Ansys/Cases/SnapFitAnalysis')
SOLVER = SOURCE/'SnapFitStaticAnalysis_files/dp0/SYS/MECH'
OUT = ROOT/'assets/projects/Pr12-Snap-Fit-Analysis'
OUT.mkdir(exist_ok=True)
media_sources = [('Directional Deformation.mp4','snap-fit-motion.mp4'),('EqStressResult.mp4','equivalent-stress.mp4'),('EqElasticStrain.mp4','equivalent-elastic-strain.mp4')]
for source, target in media_sources:
    subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(SOURCE/source),'-vf','setpts=N/(2*TB)','-r','2','-c:v','libx264','-crf','18','-pix_fmt','yuv420p','-movflags','+faststart','-an','-y',str(OUT/target)],check=True)
snapshots = [('Directional Deformation.mp4',0,'insertion-start.jpg'),('Directional Deformation.mp4',16,'motion-poster.jpg'),('Directional Deformation.mp4',19,'insertion-engaged.jpg'),('EqStressResult.mp4',16,'stress-poster.jpg'),('EqElasticStrain.mp4',16,'strain-poster.jpg')]
for source, frame, target in snapshots:
    subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(SOURCE/source),'-vf',f'select=eq(n\\,{frame})','-frames:v','1','-q:v','2','-y',str(OUT/target)],check=True)
for src, dest in [('Box Overview.JPG','assembly-overview.jpg'),('Snap-fit detail.JPG','snap-detail.jpg'),('Snap-fit stresses at Max Deflection.JPG','reference-stress.jpg')]:
    shutil.copy2(SOURCE/'Renderings'/src, OUT/dest)

history=[]
for line in (SOLVER/'file.mntr').read_text().splitlines():
    v=line.split()
    if len(v)==11 and all(x.isdigit() for x in v[:5]):
        history.append([int(x) for x in v[:5]]+[float(x) for x in v[5:]])
with (OUT/'solution-history.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.writer(f);w.writerow(['load_step','substep','attempt','iterations','cumulative_iterations','increment','load_time_s','wall_time_s','max_displacement_monitor_mm','plastic_monitor','residual_monitor']);w.writerows(history)

def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def fig(src, caption):
    return f'<figure><a href="{src}"><img src="{src}" alt="{escape(caption)}" loading="lazy"></a><figcaption>{caption}</figcaption></figure>'
video='''<figure><video controls playsinline preload="metadata" poster="motion-poster.jpg" aria-label="Complete snap-fit insertion animation, Y-direction deformation"><source src="snap-fit-motion.mp4" type="video/mp4">Your browser does not support video. <a href="snap-fit-motion.mp4">Download the motion video</a>.</video><figcaption>Updated face-on view from Directional Deformation.mp4. All 20 source frames are retained in sequence, played at 2 frames/s for 10 seconds. The legend shows Y-direction deformation in mm; the analysis spans 0–1 s. Playback is slowed visualization, not a measured insertion speed.</figcaption></figure><p><a href="snap-fit-motion.mp4" download>Download motion video</a></p>'''
sections=[]
def section(id,title,body): sections.append((id,title,body))
section('scope','Purpose and analysis scope','''<p>Document the deformation and contact sequence as a flexible snap engages its mating head. This case records a displacement-controlled insertion, from initial clearance through arm bending to final engagement.</p><p>The supplied Workbench project is titled <strong>SnapFitStaticAnalysis — Static Structural (B5)</strong>. Its solver deck uses a quasi-static transient formulation with large-deformation effects. The enclosure renderings provide application context; the solved model consists of two local bodies named <strong>snap</strong> and <strong>head</strong>.</p>'''+table(['Document control','Value'],[['Report','SF-012 / Revision 01 / 24 November 2026'],['Original analysis','ANSYS 2024 R1; solver log dated 5 March 2025'],['Evidence basis','Existing solver deck, solver log, monitor history, material data and supplied media'],['Status','Documented simulation; design acceptance remains open'],['Acceptance requirements','Insertion-force limit, retention-force target, required safety factor and allowable deformation were not supplied']]))
section('geometry','Geometry and idealization',fig('assembly-overview.jpg','Supplied enclosure rendering: context for the snap-fit application, not the complete solved ANSYS model.')+fig('snap-detail.jpg','Supplied snap-fit detail rendering.')+'''<p>The solver references <code>Snap.scdoc</code>. Both local bodies are deformable solids with the same ABS material assignment. No plastic constitutive model is defined in the input deck. Large geometry changes and frictional contact provide the modeled nonlinearities.</p><p>Dimensioned drawings, manufacturing tolerances, root radii and a documented simplification study were not supplied as report-ready evidence. The native geometry remains in the source case. The illustrated enclosure must not be interpreted as a full-assembly structural verification.</p>''')
section('materials','Material properties and units',table(['Property','Assigned value','Source'],[['Material / both bodies','Plastic, ABS (high-impact)','ds.dat model summary'],['Young’s modulus','1,628 MPa','MP,EX'],['Poisson’s ratio','0.4089','MP,NUXY'],['Density','1,030 kg/m³ (1.03 × 10⁻⁹ tonne/mm³)','MP,DENS / MatML.xml'],['Tensile yield strength','27.44 MPa at 23 °C','MatML.xml; comparison property only'],['Tensile ultimate strength','36.26 MPa at 23 °C','MatML.xml'],['Reference temperature','22 °C','tref in solver deck'],['Solver units','N, mm, s, tonne; stress in MPa','NMM /units,MPA']])+'''<p>The material library describes high-impact, injection-molding ABS. The deck uses linear elastic isotropic properties; the listed yield strength does not activate yielding. No manufacturing-specific anisotropy, creep, fatigue, plasticity or temperature-dependent loading is demonstrated. Printed-part behavior is therefore not established by this material assignment.</p>''')
section('mesh','Mesh and discretization',table(['Item','Verified value'],[['Nodes','32,248 (actual solver count, not maximum node ID)'],['Solid elements','5,712 SOLID186 elements: 4,668 and 1,044 in the two solid element types'],['Contact / target elements','304 total: 152 CONTA174 and 152 TARGE170'],['Total elements','6,016'],['Element shape checks','Disabled in solver deck; comment states prior checks in Workbench mesher'],['Mesh quality and independence','No quality histogram or mesh refinement study available']])+fig('motion-poster.jpg','Mesh visible in the supplied ANSYS animation at an intermediate insertion configuration. Colors are Y displacement, not stress.')+'''<p>A single successful mesh is documented. Stress, force and local deflection sensitivity to mesh density remain unverified. A refinement study should compare the same result quantities and locations over systematically refined meshes, especially at the arm roots and contact regions.</p>''')
section('loads','Supports, loading and contact',table(['Definition','Recovered setup'],[['Fixed support','471 nodes in _FIXEDSU; all nodal degrees of freedom fixed'],['Driven region','557 nodes in _CM127UX_XP'],['Insertion motion','Global UX ramp to +4.5 mm at analysis time 1 s'],['Lateral constraints','UY = 0 and UZ = 0 on displacement-scoped nodes'],['Contact regions','Two “Frictional - head To snap” definitions'],['Friction coefficient','0.1'],['Formulation','Augmented Lagrange'],['Normal stiffness factor','0.1; updated each equilibrium iteration'],['Penetration tolerance','0.08 mm'],['Pinball radius','0.15 mm'],['Initial contact','Solver reports all selected contact pairs initially open']])+'''<p>The scope identifiers and exact node lists are recorded in the original solver deck. Their physical face locations should be confirmed against the native model before rerunning or modifying this case. There is one forward insertion load step; no unloading, extraction or repeated cycling is defined.</p>''')
section('solver','Nonlinear solution controls',table(['Control','Setting'],[['Analysis','ANTYPE,4 with TINTP,QUAS (quasi-static transient)'],['Large deformation','On: NLGEOM,ON'],['Time stepping','Automatic; initial 20, minimum 10, maximum 25 substeps'],['End time','1 s; one load step'],['Linear solver request','PCG with 10⁻⁸ tolerance in input'],['Numerical damping','Enabled for quasi-static solution'],['Stabilization','Reduced energy method; dissipation ratio 0.0002; force limit 0.1'],['Output','All converged substeps for displacement, reactions, stresses, strains and contact data'],['Weak springs','Off in analysis settings']])+'''<p>The artificial damping and stabilization support convergence through changing contact. Their effect has not been quantified here: an energy audit and sensitivity runs are required before treating the solution as a validated quasi-static response.</p>''')
section('motion','Complete insertion motion',video+'''<ol><li><strong>Approach:</strong> the snap and mating head begin with clearance.</li><li><strong>Contact and bending:</strong> the flexible arms deflect toward each other as the head advances.</li><li><strong>Passage:</strong> the tips pass the retaining shoulders.</li><li><strong>Engagement:</strong> the arms recover toward their original shape at the final inserted position.</li></ol><p>This describes the visible sequence. Final geometric engagement does not establish pull-out resistance. The updated source is <code>Directional Deformation.mp4</code>, displaying <strong>Directional Deformation (Y Axis)</strong>. The displayed scale extends from approximately −1.4897 to +1.5003 mm; these are animation legend limits, not independently extracted maxima at every frame. The animation includes interpolated display frames between solved substeps. Its deformation display scale is not documented.</p>''')
section('stages','Insertion snapshots',fig('insertion-start.jpg','Initial configuration: first frame of the new directional-deformation export. The first-frame overlay retains Time: 1 s even though the geometry shows the starting pose; it is not used as a time measurement.')+fig('motion-poster.jpg','Deflected configuration at displayed analysis time 0.84211 s, frame 17 of 20. Full model, legend and coordinate triad retained.')+fig('insertion-engaged.jpg','Final engagement at displayed analysis time 1 s, frame 20 of 20.'))
section('result-videos','Stress and elastic-strain animations','''<p>The new face-on exports show how the arm-root stress and elastic strain develop during insertion and subside after engagement. Both clips retain all 20 source frames and use the same slowed 10-second playback as the deformation animation.</p><h3>Equivalent von Mises stress</h3><figure><video controls playsinline preload="metadata" poster="stress-poster.jpg" aria-label="Equivalent stress during snap-fit insertion"><source src="equivalent-stress.mp4" type="video/mp4"></video><figcaption>EqStressResult.mp4, converted to H.264. Fixed legend range: 0–17.172 MPa. The poster is frame 17 at displayed time 0.84211 s, close to the peak-stress substep, not the exact 0.85 s result.</figcaption></figure><p><a href="equivalent-stress.mp4" download>Download stress animation</a></p><h3>Equivalent elastic strain</h3><figure><video controls playsinline preload="metadata" poster="strain-poster.jpg" aria-label="Equivalent elastic strain during snap-fit insertion"><source src="equivalent-elastic-strain.mp4" type="video/mp4"></video><figcaption>EqElasticStrain.mp4, converted to H.264. Fixed legend range: 0–0.010551 mm/mm. Poster: frame 17 at displayed time 0.84211 s.</figcaption></figure><p><a href="equivalent-elastic-strain.mp4" download>Download elastic-strain animation</a></p><p>The saved Mechanical result tables inspected on 24 November 2026 report peak averaged equivalent stress of <strong>17.172 MPa at 0.85 s</strong> and peak equivalent elastic strain of <strong>0.010551 mm/mm (1.0551%) at 0.85 s</strong>. Averaging across bodies was disabled. These history peaks agree with the new video legend limits; the fixed limits are not per-frame extrema. No independent result-database extraction or mesh-convergence verification is claimed.</p>'''+fig('stress-poster.jpg','Equivalent stress near maximum arm deflection, from the updated ANSYS video; displayed time 0.84211 s.')+fig('strain-poster.jpg','Equivalent elastic strain at the same displayed time, from the updated ANSYS video.'))
section('results','Results and convergence record',table(['Result / check','Observation','Interpretation'],[['Solution completion','End time 1.0 reached; 14 converged substeps','The prescribed stroke was completed'],['Iteration history','113 cumulative iterations; substep 11 required a second attempt','Convergence became more demanding near snap engagement'],['Final displacement monitor','4.5000 mm','Includes prescribed translation; not a measure of arm bending alone'],['Solver messages','13 warnings; 0 errors','Completion does not eliminate contact or modeling concerns'],['Insertion / retention forces','Not numerically extracted in this report','No force target or acceptance conclusion'],['Peak averaged equivalent stress','17.172 MPa at 0.85 s','Read from saved Mechanical history; consistent with the video legend'],['Peak equivalent elastic strain','0.010551 mm/mm at 0.85 s','Read from saved Mechanical history; 1.0551%'],['Yield-to-stress ratio','27.44 / 17.172 = 1.60','Screening ratio only; mesh, contact and material validation remain open']])+table(['Substep','Analysis time (s)','Applied UX (mm)','Iterations','Max displacement monitor (mm)'],[[r[1],f'{r[6]:.3f}',f'{4.5*r[6]:.4f}',r[3],f'{r[8]:.5g}'] for r in history])+'''<p>Applied UX in this table is calculated as 4.5 × analysis time for the ramped load. The displacement-monitor column is transcribed from <code>file.mntr</code>; it is not a separately postprocessed maximum resultant deformation. <a href="solution-history.csv" download>Download the monitor history (CSV)</a>.</p>''')
section('reference','Separate stress rendering',fig('reference-stress.jpg','Supplied stress rendering for a different illustrated snap geometry. Legend: von Mises stress, 13.849 MPa maximum; stated yield strength 49 MPa.')+'''<p>This image shows a different geometry and a 49 MPa yield annotation, whereas the ANSYS material record lists 27.44 MPa. Its solver, loading, mesh and relationship to this run are not verified. It is retained as a reference image only; neither its stress nor its yield annotation is used to assess the ANSYS model. The filename “at Max Deflection” is source metadata, not an independently verified worst-case result.</p>''')
section('verification','Verification, warnings and acceptance',table(['Requirement','Evidence / remaining work'],[['Solver convergence','Run complete; inspect the original iteration and contact logs'],['Contact behavior','Warnings include abrupt contact status changes and possible spurious contact; inspect penetration, pressure and active regions'],['Force convergence','Early warning about a very small reference force; review convergence tolerances'],['Element quality','No exported quality report; solver-side shape checking disabled'],['Mesh convergence','Not demonstrated; repeat with refined arm-root and contact meshes'],['Energy and balance','Check kinetic, strain and stabilization energies, and support / driving reaction balance'],['Material validity','Confirm ABS grade, manufacturing route and applicable strain / temperature range'],['Design acceptance','Supply force targets, allowable strain / stress and safety-factor criteria'],['Validation','No physical test or independent analytical correlation supplied'],['Durability and retention','Require separate extraction, unloading, creep and cycle cases as applicable']])+'''<p><strong>Conclusion:</strong> the recorded model completes the 4.5 mm insertion and the animation shows bending followed by engagement. The available evidence supports a documented kinematic/contact demonstration. It does not yet establish an allowable insertion force, retention capacity, structural safety factor or service life.</p>''')

hero='''<section class="case-hero"><p class="case-kicker">Mechanical simulation / Nonlinear FEA / Case 12</p><h1>Snap-fit analysis<span>From first contact<br>to final engagement.</span></h1><p class="case-lead">A displacement-controlled ABS snap-fit study, documented from the ANSYS solver record with the complete insertion animation.</p><div class="case-tags"><span>ANSYS 2024 R1</span><span>Large deformation</span><span>Frictional contact</span><span>4.5 mm insertion</span></div><div class="case-actions"><a class="case-button" href="#motion">Watch complete motion</a></div></section>'''
