toc='<aside class="case-toc"><p>IN THIS REPORT</p><nav aria-label="Report sections">'+''.join(f'<a href="#{id}">{title}</a>' for id,title,_ in sections)+'</nav></aside>'
body=''.join(f'<section class="case-section" id="{id}"><h2>{title}</h2>{text}</section>' for id,title,text in sections)
footer='</main><footer class="case-footer"><p>Snap-fit analysis / Documentation revision 01</p><a href="../../../index.html#portfolio">Back to selected work</a></footer><script src="../../js/main.js"></script></body></html>'
(OUT/'report.html').write_text(head+hero+fig('motion-poster.jpg','ANSYS snap-fit insertion: Y-direction deformation and visible finite-element mesh.')+'<div class="case-layout">'+toc+'<article>'+body+'</article></div>'+footer,encoding='utf-8')

prefix='assets/projects/'+OUT.name+'/'
index=ROOT/'index.html'
html=index.read_text(encoding='utf-8')
card=f'''<div class="col-lg-4 col-md-6 portfolio-item isotope-item filter-mechanical-simulation" data-project="project-snap-fit" role="button" tabindex="0" aria-haspopup="dialog" aria-controls="project-snap-fit"><img loading="lazy" decoding="async" src="{prefix}motion-poster.jpg" class="img-fluid" alt="ANSYS snap-fit insertion mesh and deformation"><div class="portfolio-info"><span class="project-index">12 / MECHANICAL SIMULATION</span><h4>Snap-fit Analysis</h4><p>Nonlinear ABS contact analysis with a complete insertion animation and an evidence-based FEA report.</p><span class="project-open">Explore project</span></div></div>\n'''
if 'data-project="project-snap-fit"' not in html:
    marker='            </div>\n            <!-- End Portfolio Container -->'
    assert marker in html
    html=html.replace(marker,card+marker,1)
